from pathlib import Path
from openpyxl import load_workbook
from pypdf import PdfReader
root=Path('/work/workspace')
for p in sorted(root.rglob('*')):
    if not p.is_file(): continue
    print('\n'+'='*100+'\nFILE',p.relative_to(root), 'size',p.stat().st_size)
    ext=p.suffix.lower()
    try:
      if ext=='.csv':
        with p.open(errors='replace') as f:
          for i,line in enumerate(f):
            print(line.rstrip())
            if i>200: break
      elif ext=='.xlsx':
        for mode in (False, True):
          wb=load_workbook(p, data_only=mode, read_only=True)
          print('--- XLSX', 'values' if mode else 'formulas', wb.sheetnames)
          for ws in wb.worksheets:
            print('SHEET',ws.title,ws.max_row,ws.max_column)
            for row in ws.iter_rows():
              vals=[c.value for c in row]
              if any(v is not None for v in vals): print(row[0].row, vals)
          wb.close()
      elif ext=='.pdf':
        r=PdfReader(str(p)); print('pages',len(r.pages))
        for i,page in enumerate(r.pages): print(f'---PAGE {i+1}---\n'+(page.extract_text() or ''))
      elif ext in ('.docx','.pptx'):
        with zipfile.ZipFile(p) as z:
          names=[n for n in z.namelist() if (ext=='.docx' and n.startswith('word/') and n.endswith('.xml')) or (ext=='.pptx' and n.startswith('ppt/slides/slide') and n.endswith('.xml'))]
          names=sorted(names)
          for n in names:
            s=z.read(n).decode('utf-8','replace')
            # paragraphs / cells approximate
            s=re.sub(r'<w:tab[^>]*/>', '\t', s)
            s=re.sub(r'</w:p>', '\n', s)
            s=re.sub(r'</a:p>', '\n', s)
            s=re.sub(r'<[^>]+>', '', s)
            s=s.replace('&amp;','&').replace('&lt;','<').replace('&gt;','>')
            if s.strip(): print('---',n,'---\n',s)
      elif ext=='.xls':
        print('legacy xls (not yet parsed)')
    except Exception as e: print('ERROR',e)
